/* Geometry invariants and real native buttons; no desktop input. */
#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <commctrl.h>
#include <stdio.h>
#include "../app/actiondock.h"
static int passed,failed,invoked=-1,begins,ends,left,direction,selected=AD_GIT,disabled=AD_CONTENT,focused;static HWND owner,entered;
#define CHECK(label,c) do{if(c){passed++;printf("ok %s\n",label);}else{failed++;printf("FAIL %d %s\n",__LINE__,label);}}while(0)
static void query(int id,ad_state *s){s->enabled=id!=disabled;s->selected=id==selected;swprintf(s->tooltip,320,L"%ls · Shortcut",ad_labels[id]);}
static void begin(void){begins++;}static void end(void){ends++;}static void invoke(int id,POINT p){invoked=id;(void)p;}static void leave(int d){left++;direction=d;}static void focus(HWND h){focused=GetDlgCtrlID(h)-100;}
static void enter(HWND previous){entered=previous;}
static const ad_host host={query,begin,end,invoke,leave,focus,NULL,enter};
static int inside(RECT a,RECT b){return a.left>=b.left&&a.top>=b.top&&a.right<=b.right&&a.bottom<=b.bottom&&a.right>=a.left&&a.bottom>=a.top;}
static void test_dock_geometry_all_placements_and_dpi(void){int valid=1,rows=1;for(int dpi=96;dpi<=240;dpi+=48)for(int place=0;place<4;place++)for(int labels=0;labels<2;labels++)for(int width=140;width<=1400;width+=315)for(int tree=0;tree<2;tree++){ad_geometry g;int h=MulDiv(650,dpi,96);actiondock_geometry(width,h,tree,MulDiv(200,dpi,96),dpi,place,labels,AD_ALL,&g);RECT bounds={0,0,width,h};if(!inside(g.body,bounds)||!inside(g.tree,bounds)||!inside(g.dock,bounds))valid=0;if(place!=AD_HIDDEN){RECT dock={0,0,g.dock.right-g.dock.left,g.dock.bottom-g.dock.top};for(int i=0;i<AD_COUNT;i++)if(g.visible&(1u<<i))if(!inside(g.buttons[i],dock))valid=0;if(!(g.visible&(1u<<AD_MORE)))valid=0;}else if(g.visible)valid=0;if(place==AD_TREE_BOTTOM&&tree){int ys[AD_COUNT],n=0;for(int i=0;i<AD_COUNT;i++)if(g.visible&(1u<<i)){int seen=0;for(int k=0;k<n;k++)seen|=ys[k]==g.buttons[i].top;if(!seen)ys[n++]=g.buttons[i].top;}if(n>2)rows=0;}}
 CHECK("placement rectangles stay in bounds across sizes and DPI",valid);CHECK("tree dock never grows beyond two rows",rows);ad_geometry g;actiondock_geometry(1000,700,0,200,96,AD_TREE_BOTTOM,0,AD_ALL,&g);CHECK("tree hidden uses left fallback",g.effective==AD_LEFT&&g.body.left==44);actiondock_geometry(1000,700,1,200,96,AD_TREE_BOTTOM,0,AD_ALL,&g);CHECK("tree dock leaves file-pane height intact",g.body.top==0&&g.body.bottom==700&&g.tree.bottom==620&&g.visible==((1u<<AD_COUNT)-1));actiondock_geometry(560,240,1,140,96,AD_LEFT,0,AD_ALL,&g);CHECK("short strip retains More and exposes overflow",g.visible&(1u<<AD_MORE)&&g.visible!=((1u<<AD_COUNT)-1));actiondock_geometry(560,600,1,140,96,AD_TOP,1,AD_ALL,&g);CHECK("narrow labelled top row uses overflow",g.body.top==44&&g.visible&(1u<<AD_MORE)&&g.visible!=((1u<<AD_COUNT)-1));actiondock_geometry(800,600,1,200,96,AD_TREE_BOTTOM,0,0,&g);CHECK("all tools hidden still leaves recovery menu",g.visible==(1u<<AD_MORE));}
static void test_dock_native_buttons_names_tooltips_and_input(void){owner=CreateWindowExW(0,L"STATIC",L"Owned action dock",WS_POPUP,0,0,1000,700,NULL,NULL,GetModuleHandleW(NULL),NULL);CHECK("one dock window created",actiondock_create(owner,&host)!=NULL);ShowWindow(owner,SW_SHOWNOACTIVATE);ad_geometry g;actiondock_geometry(1000,700,1,200,96,AD_TREE_BOTTOM,0,AD_ALL,&g);actiondock_place(&g,96,0,GetStockObject(DEFAULT_GUI_FONT));CHECK("native disabled state follows registry query",!IsWindowEnabled(actiondock_button(AD_CONTENT))&&IsWindowEnabled(actiondock_button(AD_GIT)));wchar_t caption[100];GetWindowTextW(actiondock_button(AD_GIT),caption,100);CHECK("icon-only button retains accessible native name",!wcscmp(caption,L"Git"));GetWindowTextW(actiondock_button(AD_DIRECT),caption,100);CHECK("Direct icon has a native accessible name",!wcscmp(caption,L"Direct agent"));SendMessageW(actiondock_button(AD_DIRECT),BM_CLICK,0,0);CHECK("Direct native button dispatches its own action",invoked==AD_DIRECT);begins=ends=0;invoked=-1;HWND tooltip=NULL;/* The owning process is checked below; other app tooltips are never messaged. */
 HWND found=NULL;for(HWND h=GetTopWindow(NULL);h;h=GetWindow(h,GW_HWNDNEXT)){wchar_t cls[80];DWORD pid;GetWindowThreadProcessId(h,&pid);GetClassNameW(h,cls,80);if(pid==GetCurrentProcessId()&&!wcscmp(cls,TOOLTIPS_CLASSW)&&GetWindow(h,GW_OWNER)==GetAncestor(actiondock_window(),GA_ROOT)){found=h;break;}}tooltip=found;CHECK("owned native tooltip control created",tooltip!=NULL);if(tooltip){CHECK("all native tooltip tools registered",SendMessageW(tooltip,TTM_GETTOOLCOUNT,0,0)==AD_COUNT);wchar_t tip[320]=L"";TOOLINFOW t={.cbSize=TTTOOLINFOW_V2_SIZE,.hwnd=actiondock_window(),.uId=(UINT_PTR)actiondock_button(AD_GIT),.lpszText=tip};SendMessageW(tooltip,TTM_GETTEXTW,320,(LPARAM)&t);CHECK("tooltip carries action and shortcut",wcsstr(tip,L"Git")&&wcsstr(tip,L"Shortcut"));}
 SendMessageW(actiondock_button(AD_GIT),WM_SETFOCUS,(WPARAM)owner,0);CHECK("keyboard entry preserves previous focus source",entered==owner);SendMessageW(actiondock_button(AD_GIT),BM_CLICK,0,0);CHECK("native click invokes selected command once",invoked==AD_GIT&&begins==1&&ends==1);invoked=-1;SendMessageW(actiondock_button(AD_CONTENT),BM_CLICK,0,0);CHECK("disabled click cannot invoke",invoked==-1);SendMessageW(actiondock_button(AD_GIT),WM_KEYDOWN,VK_RETURN,0);CHECK("Enter invokes dock command",invoked==AD_GIT);SendMessageW(actiondock_button(AD_GIT),WM_KEYDOWN,VK_TAB,0);CHECK("Tab returns to host focus cycle",left==1&&direction==1);SendMessageW(actiondock_button(AD_GIT),WM_KEYDOWN,VK_ESCAPE,0);CHECK("Escape returns focus to source pane",left==2&&direction==0);SendMessageW(actiondock_button(AD_FIND),WM_KEYDOWN,VK_RIGHT,0);CHECK("arrow navigation skips disabled controls",focused==AD_COMPARE);CHECK("dock containment includes native children",actiondock_contains(actiondock_button(AD_GIT))&&!actiondock_contains(owner));actiondock_destroy();CHECK("destroy releases all owned controls",!actiondock_window()&&!actiondock_button(AD_GIT));DestroyWindow(owner);}
int wmain(void){SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);test_dock_geometry_all_placements_and_dpi();test_dock_native_buttons_names_tooltips_and_input();printf("%d passed, %d failed; 2 action dock selectors\n",passed,failed);return failed?1:0;}
